jscodeshift를 이용해서 리팩토링을 하고자 합니다. 어떻게 코드를 짜야할까요?

이전 코드입니다.
```
import { useCallback, useState } from 'react';
import { api } from 'utility';
import { useTranslation } from 'next-i18next';
import UploadFileInfo from './component/UploadFileInfo';
import UploadingOverlay from './component/UploadingOverlay';
import { DefaultModal } from '../../../component-presentation/Modal';
import UploadConfirmModalFooter from './component/UploadConfirmModalFooter';
import useUpdateElementItemBySheet from '../../../hook/(elementItemApi)/useUpdateElementItemBySheet';
import { ElementItem } from '../../../type';

const CsvUploadConfirmModal = ({
 open,
 onClose,
 csvFile,
 csvType,
 setUpdateResult,
 onUpdateAfter,
}: {
 open: boolean;
 onClose: () => void;
 csvFile: File;
 csvType: ElementItem.ContentSubmissionStatus;
 setUpdateResult: (csvFile: File, res: api.designHub.pure.elementItemsUploadBulkUpdateSheet.Post.UpdateResultModel) => void;
 onUpdateAfter?: () => void;
}): JSX.Element => {
 const { t } = useTranslation('element');
 const [isUploading, setIsUploading] = useState(false);

 const onSuccessUpdate = useCallback(
 (res: api.designHub.pure.elementItemsUploadBulkUpdateSheet.Post.ResponseModel) => {
 if (res.data) {
 setUpdateResult(csvFile, res.data);
 } else {
 console.error('성공했지만 결과 데이터가 없습니다.');
 }
 setIsUploading(false);
 onUpdateAfter?.();
 },
 [csvFile, onUpdateAfter, setUpdateResult],
 );

 const { mutate, isLoading } = useUpdateElementItemBySheet({ onSuccess: onSuccessUpdate });

 const onSubmit = useCallback(() => {
 mutate({ model: { file: csvFile, sheetCondition: csvType } });
 setIsUploading(true);
 onClose();
 }, [csvType, mutate, onClose, csvFile]);

 return (
 <>
 {isUploading && }

 }
 footerComponent={

 }
 data-f="MD-0ea7"
 />
 </>
 );
};

export default CsvUploadConfirmModal;
```

