```javascript
import jscodeshift from 'jscodeshift';

const transform = (fileInfo, api) => {
  const j = api.jscodeshift;
  const root = j(fileInfo.source);

  root
    .find(j.MemberExpression)
    .filter(
      (path) =>
        path.node.object.type === 'MemberExpression' &&
        path.node.object.object.name === 'api' &&
        (path.node.object.property.name === 'pure' || path.node.object.property.name === 'impure')
    )
    .replaceWith((path) => {
      const package = path.node.object.object.property.name;
      const type = path.node.object.property.name === 'pure' ? 'Pure' : 'Impure';
      const rest = path.node.property;

      return j.memberExpression(j.identifier(`apiRest${package}${type}`), rest);
    });

  return root.toSource();
};

export default transform;
```
